import{_ as e,o as a,c as r,aj as o}from"./chunks/framework.BwH0p-pt.js";const g=JSON.parse('{"title":"Passport Templates","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/passport/templates.md","filePath":"3.0/passport/templates.md","lastUpdated":1785836850000}'),s={name:"3.0/passport/templates.md"};function i(n,t,l,d,h,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="passport-templates" tabindex="-1">Passport Templates <a class="header-anchor" href="#passport-templates" aria-label="Permalink to &quot;Passport Templates&quot;">​</a></h1><p>A <strong>passport template</strong> defines what a Digital Product Passport contains. It is ordinary data you edit in the admin — when a regulation adds a field, you add a row, not a migration.</p><p>Find them under <strong>Catalog → Passports → Templates</strong>.</p><h2 id="anatomy-of-a-template" tabindex="-1">Anatomy of a template <a class="header-anchor" href="#anatomy-of-a-template" aria-label="Permalink to &quot;Anatomy of a template&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>Identifies the template in published data. Set once at creation and read-only afterwards.</td></tr><tr><td><strong>Applies To</strong></td><td>The attribute families whose products publish this passport. A family belongs to <strong>one</strong> template only, so families already taken by another template are not offered.</td></tr><tr><td><strong>Sections</strong></td><td>Groups of fields on the public page — <em>Materials</em>, <em>Circularity</em>, <em>Compliance</em>.</td></tr><tr><td><strong>Fields</strong></td><td>One row on the passport each.</td></tr></tbody></table><h2 id="what-a-field-carries" tabindex="-1">What a field carries <a class="header-anchor" href="#what-a-field-carries" aria-label="Permalink to &quot;What a field carries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>What the public page shows. Translatable — use the locale switcher to fill each market&#39;s language.</td></tr><tr><td><strong>Code</strong></td><td>Identifies the field in published data. Generated from the label, editable while creating, fixed once saved.</td></tr><tr><td><strong>Section</strong></td><td>Which group it appears under.</td></tr><tr><td><strong>Source</strong></td><td><em>Product attribute</em> — read the value per product; or <em>Fixed value</em> — the same localized text for every product (a take-back scheme, a warranty statement).</td></tr><tr><td><strong>Access tier</strong></td><td><strong>Consumer</strong> (public), <strong>Operator</strong> (repairers and recyclers, via a signed link) or <strong>Authority</strong> (market surveillance, via a signed link).</td></tr><tr><td><strong>Identifier role</strong></td><td>Marks a field as the <strong>GTIN</strong>, <strong>Model identifier</strong> or <strong>Batch identifier</strong>. These feed the identification block and the QR code rather than appearing as an ordinary row. Any attribute can play the role — if your GTIN lives in <code>ean</code>, point the role at <code>ean</code>.</td></tr><tr><td><strong>Required</strong></td><td>A passport will not publish in a language while this field is empty there.</td></tr></tbody></table><h2 id="create-a-template" tabindex="-1">Create a template <a class="header-anchor" href="#create-a-template" aria-label="Permalink to &quot;Create a template&quot;">​</a></h2><ol><li>Go to <strong>Catalog → Passports → Templates</strong> and click <strong>Create Template</strong>.</li><li>Enter a <strong>Name</strong>. The <strong>Code</strong> fills itself in — edit it now if you want something different.</li><li>Click <strong>Save Template</strong>. You land on the editor.</li></ol><h2 id="configure-it" tabindex="-1">Configure it <a class="header-anchor" href="#configure-it" aria-label="Permalink to &quot;Configure it&quot;">​</a></h2><h3 id="_1-choose-the-families" tabindex="-1">1. Choose the families <a class="header-anchor" href="#_1-choose-the-families" aria-label="Permalink to &quot;1. Choose the families&quot;">​</a></h3><p>Under <strong>Applies To</strong>, pick the attribute families this passport covers. Products in those families — and only those — publish through this template.</p><h3 id="_2-add-sections" tabindex="-1">2. Add sections <a class="header-anchor" href="#_2-add-sections" aria-label="Permalink to &quot;2. Add sections&quot;">​</a></h3><p><strong>Add Section</strong> → type the section name → <strong>Done</strong>. Drag the rows to reorder; the public page follows that order.</p><h3 id="_3-add-fields" tabindex="-1">3. Add fields <a class="header-anchor" href="#_3-add-fields" aria-label="Permalink to &quot;3. Add fields&quot;">​</a></h3><p><strong>Add Field</strong>, then:</p><ol><li>Type the <strong>Label</strong>; the <strong>Code</strong> is generated and stays editable.</li><li>Choose the <strong>Section</strong>.</li><li>Choose the <strong>Source</strong>: <ul><li><em>Product attribute</em> → pick the attribute. Only attributes belonging to the bound families are offered.</li><li><em>Fixed value</em> → type the text.</li></ul></li><li>Set the <strong>Access tier</strong>, an <strong>Identifier role</strong> if the field is an identifier, and switch <strong>Required</strong> on for anything a regulator mandates.</li><li><strong>Done</strong>.</li></ol><h3 id="_4-save" tabindex="-1">4. Save <a class="header-anchor" href="#_4-save" aria-label="Permalink to &quot;4. Save&quot;">​</a></h3><p>Use <strong>Save changes</strong> in the bar at the bottom.</p><div class="tip custom-block"><p class="custom-block-title">Readiness counter</p><p>The Fields header shows <em>&quot;N of M required fields sourced&quot;</em>. Leaving a field without a source is fine — it is a draft: the field publishes nothing and the counter tells you what is still open.</p></div><h2 id="translate-a-template" tabindex="-1">Translate a template <a class="header-anchor" href="#translate-a-template" aria-label="Permalink to &quot;Translate a template&quot;">​</a></h2><p>Edit any section or field row (the pencil icon) and use the locale switcher next to the label. The badge shows how many locales are filled. A label with no translation for a market falls back to the source language.</p><h2 id="reorder-edit-delete" tabindex="-1">Reorder, edit, delete <a class="header-anchor" href="#reorder-edit-delete" aria-label="Permalink to &quot;Reorder, edit, delete&quot;">​</a></h2><ul><li><strong>Reorder</strong> — drag rows by the handle. Order is the publish order.</li><li><strong>Edit</strong> — the pencil icon. Codes stay read-only, because published passports refer to them.</li><li><strong>Delete</strong> — the bin icon, then <strong>Save changes</strong>. The field stops publishing; passports already published keep their history.</li></ul>',24)])])}const u=e(s,[["render",i]]);export{g as __pageData,u as default};
